'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isPositiveZero = require( '@stdlib/math/base/assert/is-positive-zero' );
var ndarray = require( '@stdlib/ndarray/base/ctor' );
var rangeBy = require( './../lib' );


// FUNCTIONS //

/**
* Returns a one-dimensional ndarray.
*
* @private
* @param {Collection} buffer - underlying data buffer
* @param {NonNegativeInteger} length - number of indexed elements
* @param {integer} stride - stride length
* @param {NonNegativeInteger} offset - index offset
* @returns {ndarray} one-dimensional ndarray
*/
function vector( buffer, length, stride, offset ) {
	return new ndarray( 'generic', buffer, [ length ], [ stride ], offset, 'row-major' );
}

function accessor( v ) {
	if ( v === void 0 ) {
		return;
	}
	return v * 2.0;
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof rangeBy, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 1', function test( t ) {
	t.strictEqual( rangeBy.length, 1, 'has expected arity' );
	t.end();
});

tape( 'the function calculates the range of a one-dimensional ndarray via a callback function', function test( t ) {
	var x;
	var v;

	x = [ 1.0, -2.0, -4.0, 5.0, 0.0, 3.0 ];
	v = rangeBy( [ vector( x, 6, 1, 0 ), accessor ] );
	t.strictEqual( v, 18.0, 'returns expected value' );

	x = [ -4.0, -5.0 ];
	v = rangeBy( [ vector( x, 2, 1, 0 ), accessor ] );
	t.strictEqual( v, 2.0, 'returns expected value' );

	x = [ -0.0, 0.0, -0.0 ];
	v = rangeBy( [ vector( x, 3, 1, 0 ), accessor ] );
	t.strictEqual( isPositiveZero( v ), true, 'returns expected value' );

	x = [ NaN ];
	v = rangeBy( [ vector( x, 1, 1, 0 ), accessor ] );
	t.strictEqual( isnan( v ), true, 'returns expected value' );

	x = [ NaN, NaN ];
	v = rangeBy( [ vector( x, 2, 1, 0 ), accessor ] );
	t.strictEqual( isnan( v ), true, 'returns expected value' );

	x = new Array( 5 );
	v = rangeBy( [ vector( x, 5, 1, 0 ), accessor ] );
	t.strictEqual( isnan( v ), true, 'returns expected value' );

	x = new Array( 5 );
	x[ 2 ] = 1.0;
	v = rangeBy( [ vector( x, 5, 1, 0 ), accessor ] );
	t.strictEqual( v, 0.0, 'returns expected value' );

	t.end();
});

tape( 'the function supports non-unit strides', function test( t ) {
	var x;
	var v;

	x = [
		1.0,  // 0
		2.0,
		2.0,  // 1
		-7.0,
		-2.0, // 2
		3.0,
		4.0,  // 3
		2.0
	];
	v = rangeBy( [ vector( x, 4, 2, 0 ), accessor ] );
	t.strictEqual( v, 12.0, 'returns expected value' );
	t.end();
});

tape( 'the function supports negative strides', function test( t ) {
	var x;
	var v;

	x = [
		1.0,  // 3
		2.0,
		2.0,  // 2
		-7.0,
		-2.0, // 1
		3.0,
		4.0,  // 0
		2.0
	];
	v = rangeBy( [ vector( x, 4, -2, 6 ), accessor ] );
	t.strictEqual( v, 12.0, 'returns expected value' );
	t.end();
});

tape( 'the function supports non-zero offsets', function test( t ) {
	var x;
	var v;

	x = [
		1.0,
		-2.0, // 0
		3.0,
		4.0,  // 1
		5.0,
		-6.0  // 2
	];
	v = rangeBy( [ vector( x, 3, 2, 1 ), accessor ] );
	t.strictEqual( v, 20.0, 'returns expected value' );
	t.end();
});

tape( 'if provided an empty array, the function returns `NaN`', function test( t ) {
	var x = [];
	var v = rangeBy( [ vector( x, 0, 1, 0 ), accessor ] );
	t.strictEqual( isnan( v ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided a single element, the function returns `0`', function test( t ) {
	var x = [ 5.0 ];
	var v = rangeBy( [ vector( x, 1, 1, 0 ), accessor ] );
	t.strictEqual( v, 0.0, 'returns expected value' );
	t.end();
});
